import{z as i,x as A,o as E,c as l,q as t,j as o,D as e,d as B,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"遗漏变量与测量误差","description":"","frontmatter":{"title":"遗漏变量与测量误差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ovb-measurement-error.md","filePath":"econ/ovb-measurement-error.md","lastUpdated":1791063341000}'),m={name:"econ/ovb-measurement-error.md"};function d(p,a,h,F,c,_){const r=A("Mermaid");return E(),l("div",null,[a[2]||(a[2]=t('<h1 id="遗漏变量与测量误差" tabindex="-1">遗漏变量与测量误差 <a class="header-anchor" href="#遗漏变量与测量误差" aria-label="Permalink to &quot;遗漏变量与测量误差&quot;">​</a></h1><div class="epigraph"><p>漏掉与 $X$ 相关的决定因素，OLS 把别人的效应算进 $\\beta$；用误差污染的 $X$，经典测量误差把 $\\beta$ 往零拉——两种偏误形状不同，都会毁掉上一课的外生。</p><footer>—— 据 Griliches 论经济测量；Wooldridge 遗漏变量公式；对照 Bound, Brown and Mathiowetz 对调查误差</footer></div><p><a href="/econ/clustered-se">上一课</a>把簇内相关下的标准误钉死。推断修完之后，本课缺口才是外生失败的两条经典通道：遗漏变量偏误（OVB）与测量误差。工具变量下一课才出场；本课先把偏误方向钉死，避免一上来就「找一个 IV」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真模型 \\(Y=\\beta X+\\gamma W+e\\)，\\(\\mathbb{E}[e\\mid X,W]=0\\)，却回归 \\(Y\\) 对 \\(X\\)。FWL 给出</p> \\[\\mathrm{plim}\\,\\hat\\beta=\\beta+\\gamma\\cdot\\delta_{WX}, \\]<p>其中 \\(\\delta_{WX}\\) 是 \\(W\\) 对 \\(X\\) 的总体回归系数。\\(\\gamma\\) 与 \\(\\delta\\) 同号则 OVB 与真效应同向放大。能力漏在工资–教育回归里是教科书原型：教育与能力正相关，能力抬工资，OLS 高估教育回报。</p><p><span class="marginnote">数字实例：衰减因子 \\(\\frac{\\mathrm{Var}(X^*)}{\\mathrm{Var}(X^*)+\\mathrm{Var}(\\nu)}\\) 就是「信号占总方差的比例」。设真值方差 \\(\\mathrm{Var}(X^*)=1\\)、噪声方差 \\(\\mathrm{Var}(\\nu)=0.25\\)（即观测值里约两成是噪声），衰减因子就是 \\(\\frac{1}{1.25}=0.8\\)：真回报 \\(\\beta=1.0\\) 会被估成 \\(0.8\\)，噪声越大拉得越狠。</span></p><p>测量误差另一条。真 \\(X^*\\)，观测 \\(X=X^*+\\nu\\)，经典假设 \\(\\nu\\) 与 \\(X^*\\)、\\(Y\\) 的结构误差独立，则一元回归衰减：\\(\\mathrm{plim}\\,\\hat\\beta=\\beta\\cdot\\frac{\\mathrm{Var}(X^*)}{\\mathrm{Var}(X^*)+\\mathrm{Var}(\\nu)}\\)。多元里「哪一个变量被测错」决定谁衰减、谁把脏吸收到自己身上。缺口是：看见 \\(|\\hat\\beta|\\) 偏小，不要默认「不显著所以没有效应」——可能是衰减。</p><p><span class="marginnote">非经典测量误差（误差与真值相关，如顶编码、报喜不报忧）不必衰减，甚至可以反向。调查收入、自我报告处理，先问误差过程，再套经典公式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OVB：写出完整回归与短回归，用 FWL 读差。代理变量若与 \\(W\\) 相关、与 \\(e\\) 不相关，可减偏，但不能当无偏证明。固定效应把不随时间变的 \\(W\\) 吸掉——那是后课，本课只标：FE 是对<strong>时不变</strong>遗漏的装置，不是对所有遗漏的装置。</p><p><span class="marginnote">术语翻译：所谓「用第二次测量当 IV」，就是同一个变量问两遍——第一遍进回归当 \\(X\\)，第二遍只用来「照明」\\(X\\) 里的真信号。第二遍测量与 \\(Y\\) 的误差无关，但与第一遍里的真值相关，恰好满足工具变量的两个条件；两次测量的相关有多高，信号占比就有多高。</span></p><p>测量误差：重复测量、工具（用第二次测量当 IV）、外部校准。经典衰减公式只用于自变量误差；因变量的经典误差加大残差方差、不偏斜率。两边同时测错要另写。</p>',14)),(E(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRUE%5B%22%E7%9C%9F%E6%A8%A1%E5%9E%8B%E5%90%AB%20W%22%5D%20--%3E%20SHORT%5B%22%E7%9F%AD%E5%9B%9E%E5%BD%92%22%5D%0A%20%20SHORT%20--%3E%20OVB%5B%22%E5%81%8F%E8%AF%AF%20%CE%B3%C2%B7%CE%B4%22%5D%0A%20%20STAR%5B%22%E7%9C%9F%20X*%22%5D%20--%3E%20MEAS%5B%22%E8%A7%82%E6%B5%8B%20X%3DX*%2B%CE%BD%22%5D%0A%20%20MEAS%20--%3E%20ATT%5B%22%E7%BB%8F%E5%85%B8%3A%20%E5%90%91%E9%9B%B6%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OVB 的机制是相关遗漏进入残差，残差不再与 \\(X\\) 正交。测量误差的机制是 \\(X\\) 的变异掺了噪声，信号被稀释。两者可以叠加：教育年限既漏能力，又有误报。方向可能对冲，不能当「所以无偏」。</p><p>与<a href="/econ/potential-outcomes">潜在结果</a>：OVB 是 \\(\\mathbb{E}[Y(0)\\mid D=1]\\neq\\mathbb{E}[Y(0)\\mid D=0]\\) 在线性里的一种参数化。测量误差是处理或结果被错标，连 \\(D\\) 都不是真处理。随机化不自动消灭调查误差。</p><p><span class="marginnote">常见误区：初学者容易以为「只要变量测错了，系数就会往零偏」。实际上这条衰减公式只对<strong>自变量</strong>的经典误差成立；因变量的经典误差只是加大残差方差、抬高标准误，斜率本身不偏。真正危险的是处理变量（\\(D\\)）被错标——那等于把一部分人分错了组，方向可以任意。</span></p><p><span class="marginnote">Griliches 反复强调：许多「生产函数残差」先是测量问题，再是技术。先问数据生成，再问内生。</span></p>',5)),(E(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BC%B0%E8%AE%A1%E5%80%BC%E5%8F%AF%E7%96%91%2C%E6%96%B9%E5%90%91%E4%B8%8D%E6%98%8E%22%5D%20--%3E%20A%7B%22%E6%98%AF%E5%90%A6%E6%BC%8F%E4%BA%86%E4%B8%8E%20X%20%E7%9B%B8%E5%85%B3%E7%9A%84%E5%8F%98%E9%87%8F%3F%22%7D%0A%20%20A%20--%20%22%E6%98%AF%22%20--%3E%20OVB%5B%22OVB%3A%20%E5%81%8F%E8%AF%AF%20%3D%20%CE%B3%C2%B7%CE%B4%22%5D%0A%20%20OVB%20--%3E%20FIX1%5B%22%E6%8E%A7%E5%88%B6%20W%20%2F%20%E6%89%BE%E4%BB%A3%E7%90%86%20%2F%20%E5%9B%BA%E5%AE%9A%E6%95%88%E5%BA%94%22%5D%0A%20%20A%20--%20%22%E5%90%A6%22%20--%3E%20B%7B%22%E6%98%AF%E5%93%AA%E4%B8%80%E4%BE%A7%E8%A2%AB%E6%B5%8B%E9%94%99%3F%22%7D%0A%20%20B%20--%20%22%E8%87%AA%E5%8F%98%E9%87%8F%E7%BB%8F%E5%85%B8%E8%AF%AF%E5%B7%AE%22%20--%3E%20ATT%5B%22%E5%90%91%E9%9B%B6%E8%A1%B0%E5%87%8F%22%5D%0A%20%20ATT%20--%3E%20FIX2%5B%22%E9%87%8D%E5%A4%8D%E6%B5%8B%E9%87%8F%20%2F%20%E7%AC%AC%E4%BA%8C%E6%AC%A1%E6%B5%8B%E9%87%8F%E5%BD%93%20IV%22%5D%0A%20%20B%20--%20%22%E5%9B%A0%E5%8F%98%E9%87%8F%E7%BB%8F%E5%85%B8%E8%AF%AF%E5%B7%AE%22%20--%3E%20SE%5B%22%E6%96%9C%E7%8E%87%E4%B8%8D%E5%81%8F%2C%E6%A0%87%E5%87%86%E8%AF%AF%E5%8F%98%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张诊断图回答的问题与上图不同：上图画两种偏误<strong>从哪里来</strong>（数据生成路径），下图画拿到一个可疑估计后<strong>怎么分流</strong>——先问漏没漏变量，再问哪一侧被测错，最后落到对应的修复手段。两条通道可以同时存在，修复后仍要回头用 OVB 公式交代剩余方向。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IV 的存在性证明。不把控制变量清单写成「加到不显著为止」：坏控制（碰撞、中介）可以制造新偏误，Angrist–Pischke 与 Cinelli–Hazlett 的讨论留给设计课。因变量的非经典误差（如审查）走 Tobit 一类，不是本课衰减公式。量化栏的微观结构噪声是价格测量，对象不同，不搬来当教育回报。</p><p>后课默认：短回归必须用 OVB 公式交代方向；经典测量误差默认衰减。下一课在相关遗漏无法观测时，用工具把 \\(X\\) 的外生变异拆出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OVB：\\(+\\gamma\\delta\\)；符号由漏掉变量的效应与其和 \\(X\\) 的相关决定。</li><li>经典自变量测量误差向零衰减；因变量经典误差不偏斜率。</li><li>非经典误差、坏控制，都不在本课公式里。</li><li>FE 只吸时不变遗漏；不是万能。</li><li>出处：Wooldridge 教材 OVB；Griliches 测量传统；Bound, Brown and Mathiowetz 调查误差综述。</li></ul>',6))])}const V=i(m,[["render",d]]);export{D as __pageData,V as default};
